///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_openBnd
 * @description open Bnd 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_openBnd = async function () {
    const sbmOptions = {
        id: "tx_openBnd",
        method: "post",
        action: "/stdcd/stript.do?method=striptBndPop",
        ref: "dma_openBndReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_refreshPage
 * @description refresh Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_refreshPage = async function () {
    const sbmOptions = {
        id: "tx_refreshPage",
        method: "post",
        action: "/stdcd/stript.do?method=striptRegForm",
        ref: "dma_refreshPageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

