        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/stript.do?method=stripProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
