///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name openBnd
 * @description open Bnd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openBnd = async function () {
    if (($c.util.getComponent('ipt_objIsuCd').getValue() == null ? '' : String($c.util.getComponent('ipt_objIsuCd').getValue())) === '') {
        await $c.win.alert("대상채권코드(원본채권)를 선택해 주십시오.");
        $c.util.getComponent("ipt_objIsuCd").focus();
        return;
    }
    const fm = (document.JLDINF10800 || { elements: [] });
    let _popupWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/stdcd/stript.do?method=striptBndPop", unresolved: "nav:" + "/stdcd/stript.do?method=striptBndPop" }; })();
    fm.action = '/stdcd/stript.do?method=striptBndPop';

};

/**
 * @method
 * @name setPrnpIsuNm
 * @description set Prnp Isu Nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPrnpIsuNm = async function (fm) {
    if ($c.str.getByteLength($c.util.getComponent('ipt_objIsuCd').getValue()) === 0) {
        $c.util.getComponent('ipt_coupnRt').setValue("");
        await $c.win.alert("대상채권코드(원본채권)를 선택해 주십시오.");
        $c.util.getComponent("ipt_objIsuCd").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) !== 5) {
        await $c.win.alert("원금분리채권 이자율 입력시\n입력예에 따라 소수점 포함해서 5자리[예:09.09]로 입력바랍니다.");
        $c.util.getComponent("ipt_coupnRt").focus();
        return;
    }
    if ($c.num.isNumber($('#ipt_coupnRt')[0])) {
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) !== 0) {
            const int_rt = Del_Point2($('#ipt_coupnRt')[0]);
            const rdmp_dt = $c.util.getComponent('ipt_redmptDd').getValue().substring(2, 6);
            $c.util.getComponent('ipt_isuNm').setValue('국고채원금 ' + int_rt + '-' + rdmp_dt);
            $c.util.getComponent('ipt_isuEngNm').setValue('KTB PRINCIPAL STRIPS ' + int_rt + '-' + rdmp_dt);
        } else {
            $c.util.getComponent('ipt_isuNm').setValue('');
            $c.util.getComponent('ipt_isuEngNm').setValue('');
        }
    }
};

/**
 * @method
 * @name refreshPage
 * @description refresh Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.refreshPage = async function () {
    $c.util.getComponent('ipt_ldCheck').setValue('Y');
    $('#JLDINF10800')[0].action = "/stdcd/stript.do?method=striptRegForm";
    $('#JLDINF10800')[0].target = "_top";
    await moveUrl("/stdcd/stript.do?method=striptRegForm", {});
};

/**
 * @method
 * @name open_corp_cd
 * @description open corp cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_corp_cd = function () {
    formName = (document.JLDINF10800 || { elements: [] });
    fn_popupCorpSearch(formName);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_popupCorpSearch — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name Chk_form
 * @description Chk form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_form = async function () {
    const thisForm = $('#JLDINF10800');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    const telNo = $c.util.getComponent('ipt_ph01').getValue() + "-" + $c.util.getComponent('ipt_ph02').getValue() + "-" + $c.util.getComponent('ipt_ph03').getValue();
    const faxNo = $c.util.getComponent('ipt_fax01').getValue() + "-" + $c.util.getComponent('ipt_fax02').getValue() + "-" + $c.util.getComponent('ipt_fax03').getValue();
    const emailNo = $c.util.getComponent('ipt_email01').getValue() + '@' + $c.util.getComponent('ipt_email02').getValue();
    $c.util.getComponent('ipt_encrypApctEmail').setValue(emailNo);
    $c.util.getComponent('ipt_apctTelNo').setValue(telNo);
    $c.util.getComponent('ipt_apctFaxNo').setValue(faxNo);
    $c.util.getComponent('ipt_stripMajagntInstCd').setValue(($c.util.getComponent("ipt_isurCd").getValue() || ''));
    $('[key=ef_cp_rdmp_dt]').attr("name", "ef_cp_rdmp_dt");
    $('[key=ef_cp_cpn_int_rt]').attr("name", "ef_cp_cpn_int_rt");
    $('[key=ef_cp_par_tot_amt]').attr("name", "ef_cp_par_tot_amt");
    $('[key=ef_cp_isu_nm]').attr("name", "ef_cp_isu_nm");
    $('[key=ef_cp_lst_yn]').attr("name", "ef_cp_lst_yn");
    thisForm[0].action = "/stdcd/stript.do?method=stripProcess";
    thisForm[0].target = "JLDINF10800";
    await scwin.tx_Chk_form();
};

/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    const nullInput = $("table[name=conTable] input:visible[name!=''][type='text'][value='']");
    for (let i = 0; i < nullInput.length; i++) {
        if ($c.str.getByteLength($($(nullInput)[i]).val()) === 0) {
            const ipNm = $($(nullInput)[i]).attr("name");
            if ($($(nullInput)[i]).attr("id") === "nusual_isu_cond_contn") {
                continue;
            }
            const labelNm = $('[for="' + ipNm + '"]').text();
            await $c.win.alert(labelNm + "의 값이 입력되지 않았습니다.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return true;
        }
    }
    if (($c.util.getComponent('ipt_cfiCd').getValue() == null ? '' : String($c.util.getComponent('ipt_cfiCd').getValue())) === '') {
        await $c.win.alert("CFI_CD를 입력하세요");
        $c.util.getComponent("ipt_cfiCd").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_applComNm').getValue() == null ? '' : String($c.util.getComponent('ipt_applComNm').getValue())) === '') {
        await $c.win.alert("소속기관을 입력하세요");
