/**
 * @method
 * @name Reset
 * @description Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.Reset = function () {
    const restInput = $("table[name=conTable] input:visible[name!=''][type='text']");
    for (let i = 0; i < restInput.length; i++) {
        $($(restInput)[i]).val("");
    }
    const restSelect = $("table[name=conTable] select:visible");
    for (let i = 0; i < restSelect.length; i++) {
        $($(restSelect)[i]).find('option:eq(0)').attr("selected", true);
    }
    const restRadio = $("table[name=conTable] input:visible[name!=''][type='radio']");
    for (let i = 0; i < restRadio.length; i++) {
        const radioName = $($(restRadio)[i]).attr("name");
        $('input[name=' + radioName + ']:eq(0)').attr("checked", true);
    }
    $c.util.getComponent('ipt_cfiCd').setValue("DMZTFB");
    $('input[name=rd_stdCdApctTpCd]:eq(0)').attr("checked", true);
    $c.util.getComponent('ipt_applComNm').setValue("");
    $c.util.getComponent('ipt_apctNm').setValue("");
    $('#ipt_ph01').find('option:eq(0)').attr("selected", true);
    $c.util.getComponent('ipt_ph02').setValue("");
    $c.util.getComponent('ipt_ph03').setValue("");
    $('#ipt_fax01').find('option:eq(0)').attr("selected", true);
    $c.util.getComponent('ipt_fax02').setValue("");
    $c.util.getComponent('ipt_fax03').setValue("");
    $c.util.getComponent('ipt_email01').setValue("");
    $c.util.getComponent('ipt_email02').setValue("");
};

/**
 * @method
 * @name Chk_Date
 * @description Chk Date 처리
 * @param {*} Name Name
 * @param {String} Date_Str Date_Str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_Date = async function (Name, Date_Str) {
    let sdate = Name.getValue(); if (sdate == null) { sdate = ''; }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate !== "" && (syear !== soyear || smonth !== somonth || sday !== soday)) {
        await $c.win.alert("입력한 " + Date_Str + "이 올바르지 않습니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate !== "" && sdate.length !== 8) {
        await $c.win.alert("입력한 " + Date_Str + "이 8자리가 아닙니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate === "") {
        Name.setValue('');
    } else {
        Name.setValue(sdate);
    }
    return true;
};
